"""Exact tiny-instance feasibility oracle (independent of the compiler)."""
import sys, itertools
sys.path.insert(0,'/workspace/submission')
from flow import maxflow

def arborescences(nodes, root):
    """All out-arborescences on `nodes` rooted at `root` as frozensets of edges."""
    nodes = list(nodes)
    n = len(nodes)
    # enumerate all edge subsets of size n-1 over the participant pairs and test
    pairs = [(a,b) for a in nodes for b in nodes if a != b]
    res = []
    for combo in itertools.combinations(pairs, n-1):
        ine = {v:0 for v in nodes}
        adj = {}
        for (u,v) in combo:
            ine[v]+=1
            adj.setdefault(u,[]).append(v)
        if ine[root]!=0: continue
        if any(ine[v]!=1 for v in nodes if v!=root): continue
        seen={root}; st=[root]
        while st:
            u=st.pop()
            for v in adj.get(u,()):
                if v not in seen:
                    seen.add(v); st.append(v)
        if len(seen)==n:
            res.append(frozenset(combo))
    return res

def weighted_trees(trees, total, maxrec=6):
    """All multisets (tree, count) with counts>=1 summing to total."""
    out=[]
    def rec(i, rem, cur, used):
        if rem==0:
            out.append(tuple(cur)); return
        if i>=len(trees) or used>=maxrec: return
        for c in range(1, rem+1):
            rec(i+1, rem-c, cur+[(trees[i],c)], used+1)
        rec(i+1, rem, cur, used)
    rec(0, total, [], 0)
    return out

def split_paths(n, linkuv, cap, participants):
    """All simple participant-free-interior walks between participant pairs."""
    part=set(participants)
    idx={}
    for i,v in enumerate(participants):
        idx[v]=(n+2*i, n+2*i+1)
    arcs=[]; a2p=[]
    for l,(u,v) in enumerate(linkuv):
        if cap[l]<=0: continue
        for (a,b,d) in ((u,v,0),(v,u,1)):
            arcs.append((idx[a][0] if a in part else a, idx[b][1] if b in part else b, l, d))
            a2p.append((l,d))
    sn = n+2*len(participants)
    adj={i:[] for i in range(sn)}
    for i,(a,b,l,d) in enumerate(arcs):
        adj[a].append(i)
    out={}
    for u in participants:
        for v in participants:
            if u==v: continue
            src=idx[u][0]; dst=idx[v][1]
            paths=[]; 
            # DFS simple paths
            stack=[(src,frozenset([src]),())]
            while stack:
                node,seen,seq=stack.pop()
                if node==dst and seq:
                    paths.append(seq); continue
                for i in adj.get(node,()):
                    nxt=arcs[i][1]
                    if nxt in seen: continue
                    stack.append((nxt, seen|{nxt}, seq+((i,),)))
            out[(u,v)]=[(tuple(a2p[x] for x in p)) for p in paths]
    return out

def route_ok(paths, dem, cap, linkuv):
    """Exact integer multicommodity routing feasibility by DFS."""
    pairs=[p for p in dem if dem[p]>0]
    arcs=set()
    for p in pairs:
        for w in paths.get(p,()):
            arcs.update(w)
    arcl=list(arcs)
    aidx={a:i for i,a in enumerate(arcl)}
    lim=[cap[l] for (l,d) in arcl]
    load=[0]*len(arcl)
    def rec(i):
        if i>=len(pairs): return True
        p=pairs[i]; amt=dem[p]
        opts=paths.get(p,())
        if amt==0: return rec(i+1)
        # DFS over the path choices
        def assign(j, rem):
            if rem==0: return rec(i+1)
            if j>=len(opts): return False
            w=opts[j]
            need=1
            while need<=rem:
                ok=True
                for a in w:
                    k=aidx[a]
                    if load[k]+need>lim[k]: ok=False; break
                if ok:
                    for a in w:
                        k=aidx[a]; load[k]+=need
                    if assign(j, rem-need): return True
                    for a in w:
                        k=aidx[a]; load[k]-=need
                need+=1
            return assign(j+1, rem)
        return assign(0, amt)
    return rec(0)

def exact_feasible(n, linkuv, cap, participants, demand, limit_sources=3, limit_r=4):
    if len(participants)>limit_sources: return None
    if any(demand[v]>limit_r for v in participants): return None
    D=sum(demand[v] for v in participants)
    trees_by_root={}
    for v in participants:
        if demand[v]>0:
            trees_by_root[v]=weighted_trees(arborescences(participants,v), demand[v])
    paths=split_paths(n, linkuv, cap, participants)
    combos=[[1]]
    keys=list(trees_by_root)
    total=1
    for v in keys:
        total*=len(trees_by_root[v])
    if total>400000: return None
    found=False
    for choice in itertools.product(*[trees_by_root[v] for v in keys]):
        L={}
        for v,wt in zip(keys,choice):
            for (tr,c) in wt:
                for (u,w) in tr:
                    L[(u,w)]=L.get((u,w),0)+c
        dem={}
        ok=True
        for k,val in L.items():
            if val<=0: continue
            dem[k]=val
            if not paths.get(k): ok=False; break
        if not ok: continue
        if route_ok(paths, dem, cap, linkuv):
            found=True; break
    return found
